		"SELECT 1 FROM vulnerabilities WHERE id = ?", vulnerability.ID,
	).Scan(&existing); {
	case err == nil:
		return ErrDuplicateVulnerability
	case !errors.Is(err, sql.ErrNoRows):
		return fmt.Errorf("check duplicate: %w", err)
	}

