func TestBatchMatchResultsOrderProjectionAndSorting(t *testing.T) {
	router := seedMatchRouter(t)

	body := map[string]any{
		"components": []any{
			matchEntry("openssl", "1.1"),
			matchEntry("libxml2", "2.4.1"),
			matchEntry("libxml2", "9.9.9"),
			matchEntry("LIBXML2", "2.4.1"),
			matchEntry("libxml2", "2.4.1"),
			matchEntry("missing", "1.0"),
			matchEntry("libxml2", "1.5"),
		},
	}
	response := decodeMatchResponse(t, postMatch(t, router, body))
	if len(response.Results) != 7 {
		t.Fatalf("results = %d, want 7: %s", len(response.Results), response)
	}

	for index, want := range []struct {
		component string
		version   string
		count     int
	}{
		{"openssl", "1.1", 1},
		{"libxml2", "2.4.1", 2},
		{"libxml2", "9.9.9", 0},
		{"LIBXML2", "2.4.1", 1},
		{"libxml2", "2.4.1", 2},
		{"missing", "1.0", 0},
		{"libxml2", "1.5", 1},
	} {
		got := response.Results[index]
		if got.Component != want.component || got.Version != want.version {
			t.Fatalf("result %d echo = (%q,%q), want (%q,%q)", index, got.Component, got.Version, want.component, want.version)
		}
		if len(got.Vulnerabilities) != want.count {
			t.Fatalf("result %d (%s@%s) hits = %d, want %d", index, want.component, want.version, len(got.Vulnerabilities), want.count)
		}
	}

	libxmlHits := response.Results[1].Vulnerabilities
	if libxmlHits[0].ID != "CVE-2024-0002" || libxmlHits[1].ID != "CVE-2024-0010" {
		t.Fatalf("vulnerabilities not sorted by id: %v", libxmlHits)
	}
	first := libxmlHits[0]
	if first.Component != "libxml2" || first.Severity != "high" ||
		first.FixedVersion != "2.10.0" || first.Status != "open" {
		t.Fatalf("projection fields wrong: %v", first)
	}
	if len(first.Ranges) != 1 {
		t.Fatalf("matched_ranges = %v, want only the single hit range", first.Ranges)
	}
	hitRange := first.Ranges[0]
	if hitRange.Lower == nil || *hitRange.Lower != "2.0" || hitRange.LowerInclude == nil || !*hitRange.LowerInclude ||
		hitRange.Upper == nil || *hitRange.Upper != "2.9" || hitRange.UpperInclude == nil || *hitRange.UpperInclude {
		t.Fatalf("matched range wrong: %v", hitRange)
	}

	upperOnlyHit := libxmlHits[1]
	if upperOnlyHit.ID != "CVE-2024-0010" || upperOnlyHit.Status != "fixed" {
		t.Fatalf("fixed-status vulnerability must still match: %v", upperOnlyHit)
	}
	if len(upperOnlyHit.Ranges) != 1 || upperOnlyHit.Ranges[0].Lower != nil {
		t.Fatalf("open lower bound must serialize as null: %v", upperOnlyHit.Ranges)
	}

	opensslHit := response.Results[0].Vulnerabilities[0]
	if opensslHit.ID != "CVE-2024-0005" || opensslHit.Component != "openssl" {
		t.Fatalf("openssl hit wrong: %v", opensslHit)
	}
}

