func TestBatchMatchAcceptsUpTo100Entries(t *testing.T) {
	router := seedMatchRouter(t)

	components := make([]any, 100)
	for index := range components {
		components[index] = matchEntry("libxml2", "2.4.1")
	}
	response := decodeMatchResponse(t, postMatch(t, router, map[string]any{"components": components}))
	if len(response.Results) != 100 {
		t.Fatalf("results = %d, want 100", len(response.Results))
	}

	over := append(components, matchEntry("libxml2", "2.4.1"))
	recorder := postMatch(t, router, map[string]any{"components": over})
	if recorder.Code != http.StatusBadRequest || recorder.Body.String() != "error=INVALID_INPUT" {
		t.Fatalf("101 entries: status=%d body=%q", recorder.Code, recorder.Body.String())
	}
}

