func TestBatchMatchInvalidInputs(t *testing.T) {
	validComponents := []any{matchEntry("libxml2", "2.4.1")}

	cases := map[string]any{
		"array body":              []any{matchEntry("libxml2", "1.0")},
		"string body":             "components",
		"null body":               nil,
		"missing components":      map[string]any{},
		"components null":         map[string]any{"components": nil},
		"components empty":        map[string]any{"components": []any{}},
		"components not array":    map[string]any{"components": "nope"},
		"element not object":      map[string]any{"components": []any{"nope"}},
		"element null":            map[string]any{"components": []any{nil}},
		"missing component":       map[string]any{"components": []any{map[string]any{"version": "1.0"}}},
		"empty component":         map[string]any{"components": []any{matchEntry("", "1.0")}},
		"component not string":    map[string]any{"components": []any{map[string]any{"component": 7, "version": "1.0"}}},
		"missing version":         map[string]any{"components": []any{map[string]any{"component": "libxml2"}}},
		"empty version":           map[string]any{"components": []any{matchEntry("libxml2", "")}},
		"bad version":             map[string]any{"components": []any{matchEntry("libxml2", "1.x")}},
		"version trailing dot":    map[string]any{"components": []any{matchEntry("libxml2", "1.0.")}},
		"version not string":      map[string]any{"components": []any{map[string]any{"component": "libxml2", "version": 4}}},
		"valid then bad":          map[string]any{"components": []any{matchEntry("libxml2", "1.0"), matchEntry("libxml2", "")}},
		"bad then valid":          map[string]any{"components": []any{matchEntry("libxml2", ""), matchEntry("libxml2", "1.0")}},
		"101 valid entries":       map[string]any{"components": matchComponentList(101)},
		"duplicate does not fix":  map[string]any{"components": append(matchComponentList(100), matchEntry("libxml2", ""))},
		"unrelated does not fix":  map[string]any{"components": validComponents, "bogus": nil},
	}
	for name, body := range cases {
		t.Run(name, func(t *testing.T) {
			router := seedMatchRouter(t)
			recorder := postMatch(t, router, body)
			if recorder.Code != http.StatusBadRequest || recorder.Body.String() != "error=INVALID_INPUT" {
				t.Fatalf("status=%d body=%q", recorder.Code, recorder.Body.String())
			}
			if contentType := recorder.Header().Get("Content-Type"); contentType != "text/plain; charset=utf-8" {
				t.Fatalf("content-type = %q", contentType)
			}
		})
	}
}

